CREATE TABLE schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE users (id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, auth_secret_hash TEXT NOT NULL, login_salt TEXT NOT NULL, login_iterations INTEGER NOT NULL, recovery_hash TEXT NOT NULL DEFAULT '', recovery_used_at TEXT NOT NULL DEFAULT '', role TEXT NOT NULL DEFAULT 'user', status TEXT NOT NULL DEFAULT 'active', quota_bytes INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, csrf_hash TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, hard_expires_at TEXT NOT NULL, revoked_at TEXT NOT NULL DEFAULT '');
CREATE TABLE containers (id TEXT PRIMARY KEY, kind TEXT NOT NULL, owner_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, team_id TEXT NOT NULL DEFAULT '', key_generation INTEGER NOT NULL DEFAULT 1, change_seq INTEGER NOT NULL DEFAULT 0, meta_ciphertext BLOB NOT NULL DEFAULT x'', meta_version INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT NOT NULL DEFAULT '');
CREATE TABLE blobs (digest TEXT PRIMARY KEY, size_bytes INTEGER NOT NULL, created_at TEXT NOT NULL, unreferenced_since TEXT NOT NULL DEFAULT '');
CREATE TABLE blob_containers (digest TEXT NOT NULL REFERENCES blobs(digest) ON DELETE CASCADE, container_id TEXT NOT NULL REFERENCES containers(id) ON DELETE CASCADE, first_seen_at TEXT NOT NULL, PRIMARY KEY(digest,container_id));
CREATE TABLE objects (id TEXT PRIMARY KEY, container_id TEXT NOT NULL REFERENCES containers(id) ON DELETE CASCADE, kind TEXT NOT NULL, current_version INTEGER NOT NULL DEFAULT 0, change_seq INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT NOT NULL DEFAULT '');
CREATE TABLE object_versions (object_id TEXT NOT NULL REFERENCES objects(id) ON DELETE CASCADE, version INTEGER NOT NULL, blob_digest TEXT NOT NULL REFERENCES blobs(digest), ciphertext_bytes INTEGER NOT NULL, key_generation INTEGER NOT NULL, author_device_id TEXT NOT NULL DEFAULT '', base_version INTEGER NOT NULL DEFAULT 0, change_seq INTEGER NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(object_id,version));
